import { useState, useEffect, useRef } from 'react';

const SOURCES = {
  "17": { code: "\"\"\"\nSistema di alerting per attivit\u00e0 vulcanologica.\n\nMonitora il tremore vulcanico e genera allerte in base all'ampiezza\ndel segnale su diverse bande di frequenza e agli spostamenti GPS.\n\nIssue #17 \u2014 PROBLEMA DI DESIGN: le 12 soglie di allerta sono hardcoded\nnel corpo di evaluate_alert come letterali numerici. Questo impedisce:\n1. La calibrazione per stazione senza modificare il sorgente\n2. Il testing con soglie controllate\n3. L'aggiornamento operativo senza rilascio del codice\n\nIl refactoring deve:\n- Estrarre le soglie in un dizionario opzionale `thresholds: dict | None = None`\n- Se None, usare i valori attuali come default (retrocompatibilit\u00e0 obbligatoria)\n- Supportare override per singola stazione via `station_overrides: dict | None = None`\n- Aggiungere `summarize_alerts()` per statistiche aggregate\n- Garantire che tutti i test attuali in TestEvaluateAlertDefault passino invariati\n\"\"\"\n\nfrom dataclasses import dataclass\nfrom enum import Enum\nfrom typing import Optional\n\n\nclass AlertLevel(Enum):\n    GREEN  = \"green\"\n    YELLOW = \"yellow\"\n    ORANGE = \"orange\"\n    RED    = \"red\"\n\n\n@dataclass\nclass TremorReading:\n    \"\"\"Lettura di tremore vulcanico da una stazione.\"\"\"\n    station: str\n    timestamp: float\n    amplitude_low: float\n    amplitude_mid: float\n    amplitude_high: float\n    displacement: float\n    quality_factor: float = 1.0\n\n\n@dataclass\nclass Alert:\n    \"\"\"Allerta generata dal sistema.\"\"\"\n    station: str\n    timestamp: float\n    level: AlertLevel\n    reason: str\n    reading: TremorReading\n    threshold_source: str = \"default\"\n\n\ndef evaluate_alert(reading: TremorReading) -> Alert:\n    \"\"\"\n    Valuta una lettura di tremore e restituisce il livello di allerta.\n\n    Issue #17 \u2014 soglie hardcoded da estrarre:\n        LOW_YELLOW=0.3, LOW_ORANGE=0.6, LOW_RED=0.9\n        MID_YELLOW=0.4, MID_ORANGE=0.7, MID_RED=1.1\n        HIGH_YELLOW=0.2, HIGH_ORANGE=0.5, HIGH_RED=0.85\n        DISP_YELLOW=2.0, DISP_ORANGE=5.0, DISP_RED=10.0\n    \"\"\"\n    if (reading.amplitude_low  >= 0.9 or\n        reading.amplitude_mid  >= 1.1 or\n        reading.amplitude_high >= 0.85 or\n        reading.displacement   >= 10.0):\n        return Alert(station=reading.station, timestamp=reading.timestamp,\n                     level=AlertLevel.RED,\n                     reason=_build_reason(reading, \"RED\"),\n                     reading=reading)\n\n    if (reading.amplitude_low  >= 0.6 or\n        reading.amplitude_mid  >= 0.7 or\n        reading.amplitude_high >= 0.5 or\n        reading.displacement   >= 5.0):\n        return Alert(station=reading.station, timestamp=reading.timestamp,\n                     level=AlertLevel.ORANGE,\n                     reason=_build_reason(reading, \"ORANGE\"),\n                     reading=reading)\n\n    if (reading.amplitude_low  >= 0.3 or\n        reading.amplitude_mid  >= 0.4 or\n        reading.amplitude_high >= 0.2 or\n        reading.displacement   >= 2.0):\n        return Alert(station=reading.station, timestamp=reading.timestamp,\n                     level=AlertLevel.YELLOW,\n                     reason=_build_reason(reading, \"YELLOW\"),\n                     reading=reading)\n\n    return Alert(station=reading.station, timestamp=reading.timestamp,\n                 level=AlertLevel.GREEN,\n                 reason=\"Nessuna anomalia rilevata\",\n                 reading=reading)\n\n\ndef batch_evaluate(readings: list[TremorReading]) -> list[Alert]:\n    \"\"\"Valuta una lista di letture. Issue #17: aggiungere parametri thresholds e include_green.\"\"\"\n    return [evaluate_alert(r) for r in readings]\n\n\ndef highest_alert(alerts: list[Alert]) -> Optional[Alert]:\n    \"\"\"Restituisce l'allerta con livello pi\u00f9 alto dalla lista.\"\"\"\n    if not alerts:\n        return None\n    order = [AlertLevel.GREEN, AlertLevel.YELLOW, AlertLevel.ORANGE, AlertLevel.RED]\n    return max(alerts, key=lambda a: order.index(a.level))\n\n\ndef summarize_alerts(alerts: list[Alert]) -> dict:\n    \"\"\"\n    Produce un riepilogo delle allerte per una sessione di monitoraggio.\n\n    Issue #17: da implementare durante il refactoring.\n    Returns:\n        Dizionario con conteggi per livello, stazione pi\u00f9 attiva,\n        e timestamp della prima e ultima allerta non-GREEN.\n    \"\"\"\n    raise NotImplementedError(\"Issue #17 \u2014 da implementare\")\n\n\ndef _build_reason(reading: TremorReading, level: str) -> str:\n    parts = []\n    if reading.amplitude_high >= 0.2:\n        parts.append(f\"tremore HF={reading.amplitude_high:.2f}\")\n    if reading.amplitude_mid >= 0.4:\n        parts.append(f\"tremore MF={reading.amplitude_mid:.2f}\")\n    if reading.amplitude_low >= 0.3:\n        parts.append(f\"tremore LF={reading.amplitude_low:.2f}\")\n    if reading.displacement >= 2.0:\n        parts.append(f\"spostamento={reading.displacement:.1f}mm\")\n    return f\"Livello {level}: \" + \", \".join(parts) if parts else f\"Livello {level}\"\n", test: "\"\"\"\nTest per seismolab/alerts/volcanic.py\n\nCopertura richiesta dall'issue #17:\n- evaluate_alert: tutti i livelli con soglie default\n- evaluate_alert: retrocompatibilit\u00e0 (chiamata senza thresholds)\n- evaluate_alert: soglie custom tramite parametro\n- evaluate_alert: override per stazione (STRO01, ETNA02)\n- batch_evaluate: liste miste, filtro GREEN\n- highest_alert: ordinamento corretto\n- summarize_alerts: statistiche aggregate\n\"\"\"\n\nimport pytest\nfrom seismolab.alerts.volcanic import (\n    evaluate_alert, batch_evaluate, highest_alert, summarize_alerts,\n    AlertLevel, TremorReading, Alert,\n)\nfrom tests.conftest import BASE_TIME\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# evaluate_alert \u2014 soglie default (retrocompatibilit\u00e0)\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestEvaluateAlertDefault:\n\n    def test_green_below_all_thresholds(self, reading_green):\n        alert = evaluate_alert(reading_green)\n        assert alert.level == AlertLevel.GREEN\n\n    def test_yellow_triggered_by_low_amplitude(self, reading_yellow_low):\n        alert = evaluate_alert(reading_yellow_low)\n        assert alert.level == AlertLevel.YELLOW\n\n    def test_orange_triggered(self, reading_orange):\n        alert = evaluate_alert(reading_orange)\n        assert alert.level == AlertLevel.ORANGE\n\n    def test_red_triggered(self, reading_red):\n        alert = evaluate_alert(reading_red)\n        assert alert.level == AlertLevel.RED\n\n    def test_alert_station_preserved(self, reading_green):\n        alert = evaluate_alert(reading_green)\n        assert alert.station == reading_green.station\n\n    def test_alert_timestamp_preserved(self, reading_green):\n        alert = evaluate_alert(reading_green)\n        assert alert.timestamp == BASE_TIME\n\n    def test_threshold_boundary_yellow_exact(self):\n        \"\"\"Un valore esattamente sulla soglia YELLOW deve dare YELLOW.\"\"\"\n        reading = TremorReading(\n            station=\"ETNA01\", timestamp=BASE_TIME,\n            amplitude_low=0.3,    # esattamente LOW_YELLOW\n            amplitude_mid=0.0,\n            amplitude_high=0.0,\n            displacement=0.0,\n        )\n        assert evaluate_alert(reading).level == AlertLevel.YELLOW\n\n    def test_threshold_just_below_yellow(self):\n        \"\"\"Un valore appena sotto la soglia YELLOW deve dare GREEN.\"\"\"\n        reading = TremorReading(\n            station=\"ETNA01\", timestamp=BASE_TIME,\n            amplitude_low=0.299,  # appena sotto LOW_YELLOW=0.3\n            amplitude_mid=0.0,\n            amplitude_high=0.0,\n            displacement=0.0,\n        )\n        assert evaluate_alert(reading).level == AlertLevel.GREEN\n\n    def test_displacement_alone_triggers_yellow(self):\n        \"\"\"Il solo spostamento GPS sopra la soglia deve dare YELLOW.\"\"\"\n        reading = TremorReading(\n            station=\"ETNA01\", timestamp=BASE_TIME,\n            amplitude_low=0.0, amplitude_mid=0.0, amplitude_high=0.0,\n            displacement=2.5,   # > DISP_YELLOW=2.0\n        )\n        assert evaluate_alert(reading).level == AlertLevel.YELLOW\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# evaluate_alert \u2014 soglie custom e override stazione\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestEvaluateAlertCustomThresholds:\n\n    def test_custom_thresholds_override_defaults(self):\n        \"\"\"Con soglie personalizzate, i livelli cambiano di conseguenza.\"\"\"\n        reading = TremorReading(\n            station=\"TEST\", timestamp=BASE_TIME,\n            amplitude_low=0.5, amplitude_mid=0.0,\n            amplitude_high=0.0, displacement=0.0,\n        )\n        # Con default: 0.5 >= LOW_ORANGE=0.6? No \u2192 YELLOW\n        default_alert = evaluate_alert(reading)\n        assert default_alert.level == AlertLevel.YELLOW\n\n        # Con soglie custom abbassate: 0.5 >= LOW_ORANGE=0.4? S\u00ec \u2192 ORANGE\n        custom = {\"LOW_YELLOW\": 0.2, \"LOW_ORANGE\": 0.4, \"LOW_RED\": 0.8,\n                  \"MID_YELLOW\": 0.4, \"MID_ORANGE\": 0.7, \"MID_RED\": 1.1,\n                  \"HIGH_YELLOW\": 0.2, \"HIGH_ORANGE\": 0.5, \"HIGH_RED\": 0.85,\n                  \"DISP_YELLOW\": 2.0, \"DISP_ORANGE\": 5.0, \"DISP_RED\": 10.0}\n        custom_alert = evaluate_alert(reading, thresholds=custom)\n        assert custom_alert.level == AlertLevel.ORANGE\n\n    def test_stro01_override_raises_threshold(self, reading_stro_yellow):\n        \"\"\"STRO01 ha soglie alzate: reading_orange deve dare YELLOW, non ORANGE.\"\"\"\n        alert = evaluate_alert(reading_stro_yellow)\n        assert alert.level == AlertLevel.YELLOW\n        assert alert.threshold_source == \"station_override\"\n\n    def test_etna01_no_override_uses_default(self, reading_orange):\n        alert = evaluate_alert(reading_orange)\n        assert alert.threshold_source == \"default\"\n\n    def test_custom_thresholds_source_label(self, reading_green):\n        custom = {k: 99.0 for k in [\n            \"LOW_YELLOW\",\"LOW_ORANGE\",\"LOW_RED\",\n            \"MID_YELLOW\",\"MID_ORANGE\",\"MID_RED\",\n            \"HIGH_YELLOW\",\"HIGH_ORANGE\",\"HIGH_RED\",\n            \"DISP_YELLOW\",\"DISP_ORANGE\",\"DISP_RED\",\n        ]}\n        alert = evaluate_alert(reading_green, thresholds=custom)\n        assert alert.threshold_source == \"custom\"\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# batch_evaluate\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestBatchEvaluate:\n\n    def test_batch_returns_one_per_reading(\n        self, reading_green, reading_yellow_low, reading_orange\n    ):\n        alerts = batch_evaluate([reading_green, reading_yellow_low, reading_orange])\n        assert len(alerts) == 3\n\n    def test_batch_filters_green(self, reading_green, reading_yellow_low):\n        alerts = batch_evaluate(\n            [reading_green, reading_yellow_low], include_green=False\n        )\n        assert len(alerts) == 1\n        assert alerts[0].level == AlertLevel.YELLOW\n\n    def test_batch_empty_input(self):\n        assert batch_evaluate([]) == []\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# highest_alert e summarize_alerts\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestAlertAggregation:\n\n    def test_highest_alert_selects_red(\n        self, reading_green, reading_yellow_low, reading_red\n    ):\n        alerts = batch_evaluate([reading_green, reading_yellow_low, reading_red])\n        peak = highest_alert(alerts)\n        assert peak.level == AlertLevel.RED\n\n    def test_highest_alert_empty_list(self):\n        assert highest_alert([]) is None\n\n    def test_summarize_counts_by_level(\n        self, reading_green, reading_yellow_low, reading_orange\n    ):\n        alerts = batch_evaluate([reading_green, reading_yellow_low, reading_orange])\n        summary = summarize_alerts(alerts)\n        assert summary[\"by_level\"][\"green\"] == 1\n        assert summary[\"by_level\"][\"yellow\"] == 1\n        assert summary[\"by_level\"][\"orange\"] == 1\n        assert summary[\"total\"] == 3\n\n    def test_summarize_empty(self):\n        summary = summarize_alerts([])\n        assert summary[\"total\"] == 0\n", label: "#17 \u2014 Soglie vulcaniche", file: "seismolab/alerts/volcanic.py", testfile: "tests/test_volcanic.py" },
  "23": { code: "\"\"\"\nQuery su dati GPS da database PostGIS.\n\nIl database registra misurazioni GPS di stazioni della rete geodetica INGV.\nLe stazioni monitorano la deformazione del suolo su Etna, Stromboli, Campi Flegrei\ne altre aree vulcaniche attive.\n\nIssue #23 \u2014 FEATURE: implementare le quattro funzioni di query.\nIl modulo definisce l'interfaccia e i tipi di ritorno; il corpo delle funzioni\nva implementato usando psycopg2 con query parametrizzate.\n\nSchema del database (tabelle rilevanti):\n\n    CREATE TABLE stations (\n        code        VARCHAR(10) PRIMARY KEY,\n        name        TEXT NOT NULL,\n        volcano     VARCHAR(50),\n        latitude    DOUBLE PRECISION NOT NULL,\n        longitude   DOUBLE PRECISION NOT NULL,\n        elevation   DOUBLE PRECISION NOT NULL,\n        active      BOOLEAN DEFAULT TRUE\n    );\n\n    CREATE TABLE gps_measurements (\n        id          BIGSERIAL PRIMARY KEY,\n        station     VARCHAR(10) NOT NULL REFERENCES stations(code),\n        recorded_at TIMESTAMPTZ NOT NULL,\n        latitude    DOUBLE PRECISION NOT NULL,\n        longitude   DOUBLE PRECISION NOT NULL,\n        elevation   DOUBLE PRECISION NOT NULL,\n        delta_n     DOUBLE PRECISION,   -- spostamento Nord (mm)\n        delta_e     DOUBLE PRECISION,   -- spostamento Est (mm)\n        delta_u     DOUBLE PRECISION,   -- spostamento verticale (mm)\n        quality     SMALLINT DEFAULT 1  -- 0=scadente 1=accettabile 2=ottimo\n    );\n\n    CREATE INDEX gps_station_time ON gps_measurements(station, recorded_at DESC);\n\nConfigurazione connessione via variabili d'ambiente:\n    DB_HOST, DB_PORT, DB_NAME, DB_USER, DB_PASSWORD\n\"\"\"\n\nimport os\nfrom dataclasses import dataclass\nfrom typing import Optional, Callable\nfrom datetime import datetime, timedelta, timezone\n\n\n@dataclass\nclass GpsMeasurement:\n    \"\"\"Singola misurazione GPS.\"\"\"\n    station: str\n    recorded_at: datetime\n    latitude: float\n    longitude: float\n    elevation: float\n    delta_n: Optional[float] = None   # spostamento Nord (mm)\n    delta_e: Optional[float] = None   # spostamento Est (mm)\n    delta_u: Optional[float] = None   # spostamento verticale (mm)\n    quality: int = 1\n\n    @property\n    def displacement_magnitude(self) -> Optional[float]:\n        \"\"\"Magnitudo del vettore di spostamento orizzontale in mm.\"\"\"\n        if self.delta_n is None or self.delta_e is None:\n            return None\n        return (self.delta_n ** 2 + self.delta_e ** 2) ** 0.5\n\n    @property\n    def is_high_quality(self) -> bool:\n        return self.quality >= 2\n\n\n@dataclass\nclass DisplacementSummary:\n    \"\"\"Riepilogo degli spostamenti per una stazione in un periodo.\"\"\"\n    station: str\n    period_days: int\n    measurement_count: int\n    max_horizontal_mm: Optional[float]\n    max_vertical_mm: Optional[float]\n    mean_horizontal_mm: Optional[float]\n    trend_n: str     # 'stable' | 'increasing' | 'decreasing'\n    trend_e: str\n    trend_u: str\n    first_measurement: Optional[datetime]\n    last_measurement: Optional[datetime]\n\n    @property\n    def overall_trend(self) -> str:\n        \"\"\"Trend dominante basato sul componente con variazione maggiore.\"\"\"\n        trends = [self.trend_n, self.trend_e, self.trend_u]\n        if \"increasing\" in trends:\n            return \"increasing\"\n        if \"decreasing\" in trends:\n            return \"decreasing\"\n        return \"stable\"\n\n\ndef get_connection(dsn: Optional[str] = None):\n    \"\"\"\n    Restituisce una connessione psycopg2 al database PostGIS.\n\n    Legge le credenziali dalle variabili d'ambiente se dsn \u00e8 None.\n    Solleva EnvironmentError se mancano variabili obbligatorie.\n    Solleva psycopg2.OperationalError se la connessione fallisce.\n\n    Args:\n        dsn: stringa di connessione opzionale (sovrascrive env vars)\n             es. \"host=localhost dbname=seismodb user=ingv password=...\"\n\n    TODO (Issue #23): implementare questa funzione.\n    Requisiti:\n    - Usa psycopg2.connect()\n    - Se dsn \u00e8 None, costruisci il dsn da variabili d'ambiente:\n      DB_HOST (default: localhost), DB_PORT (default: 5432),\n      DB_NAME, DB_USER, DB_PASSWORD (queste ultime tre obbligatorie)\n    - Imposta autocommit=False\n    - Non aprire connessioni nei test: usa il parametro conn nelle altre funzioni\n    \"\"\"\n    raise NotImplementedError(\"Issue #23 \u2014 da implementare\")\n\n\ndef fetch_recent_measurements(\n    station: str,\n    hours: int = 24,\n    conn=None,\n    min_quality: int = 0,\n) -> list[GpsMeasurement]:\n    \"\"\"\n    Recupera le misurazioni GPS delle ultime N ore per una stazione.\n\n    Args:\n        station:     codice stazione (es. 'ETNA01', 'STRO02')\n        hours:       finestra temporale in ore (default: 24)\n        conn:        connessione psycopg2 (se None, ne crea una con get_connection)\n        min_quality: qualit\u00e0 minima dei record da includere [0, 1, 2]\n\n    Returns:\n        Lista di GpsMeasurement ordinata per recorded_at crescente.\n        Lista vuota se non ci sono misurazioni nel periodo.\n\n    Raises:\n        psycopg2.OperationalError: se la connessione fallisce\n        ValueError: se hours <= 0\n\n    TODO (Issue #23): implementare questa funzione.\n    Requisiti:\n    - Query parametrizzata con %s (mai f-string, mai format())\n    - Filtro temporale: recorded_at >= NOW() - (%s * INTERVAL '1 hour')\n      (un segnaposto dentro una stringa quotata non viene sostituito)\n    - Filtro qualit\u00e0: quality >= %s\n    - Ordina per recorded_at ASC\n    - Usa context manager per il cursore\n    - Se conn \u00e8 None, apri e chiudi la connessione internamente\n    \"\"\"\n    raise NotImplementedError(\"Issue #23 \u2014 da implementare\")\n\n\ndef fetch_displacement_summary(\n    station: str,\n    days: int = 7,\n    conn=None,\n) -> DisplacementSummary:\n    \"\"\"\n    Calcola un riepilogo degli spostamenti degli ultimi N giorni.\n\n    Il trend \u00e8 calcolato confrontando la media della prima e seconda met\u00e0\n    del periodo: se la seconda met\u00e0 supera la prima di pi\u00f9 del 20%,\n    il trend \u00e8 'increasing'; se \u00e8 inferiore del 20%, 'decreasing';\n    altrimenti 'stable'.\n\n    Args:\n        station: codice stazione\n        days:    finestra temporale in giorni (default: 7)\n        conn:    connessione psycopg2 opzionale\n\n    Returns:\n        DisplacementSummary con statistiche e trend per componente.\n        Se non ci sono misurazioni, restituisce un summary con\n        measurement_count=0 e tutti i valori None.\n\n    Raises:\n        psycopg2.OperationalError: se la connessione fallisce\n        ValueError: se days <= 0\n\n    TODO (Issue #23): implementare questa funzione.\n    Requisiti:\n    - Una singola query SQL che recupera le misurazioni del periodo\n    - Calcola max/mean di displacement_magnitude in Python (non in SQL)\n    - Calcola trend confrontando prima e seconda met\u00e0 del periodo\n    - Usa query parametrizzata con %s\n    \"\"\"\n    raise NotImplementedError(\"Issue #23 \u2014 da implementare\")\n\n\ndef watch_anomalies(\n    stations: list[str],\n    threshold_mm: float,\n    callback: Callable[[str, GpsMeasurement], None],\n    hours: int = 1,\n    conn=None,\n) -> int:\n    \"\"\"\n    Controlla le misurazioni recenti e chiama callback per ogni anomalia.\n\n    Una misurazione \u00e8 anomala se displacement_magnitude > threshold_mm.\n\n    Args:\n        stations:      lista di codici stazione da monitorare\n        threshold_mm:  soglia di spostamento orizzontale in mm\n        callback:      funzione chiamata con (station, measurement) per ogni anomalia\n        hours:         finestra temporale in ore (default: 1)\n        conn:          connessione psycopg2 opzionale\n\n    Returns:\n        Numero di anomalie rilevate (quante volte callback \u00e8 stato chiamato).\n\n    Raises:\n        psycopg2.OperationalError: se la connessione fallisce\n        ValueError: se threshold_mm <= 0\n\n    TODO (Issue #23): implementare questa funzione.\n    Requisiti:\n    - Chiama fetch_recent_measurements per ogni stazione\n    - Filtra le misurazioni dove displacement_magnitude > threshold_mm\n    - Chiama callback per ogni misurazione anomala\n    - Gestisce le eccezioni per singola stazione senza interrompere il loop\n    - Non eseguire N query separate: considera un'unica query con IN (%s, %s, ...)\n    \"\"\"\n    raise NotImplementedError(\"Issue #23 \u2014 da implementare\")\n", test: "\"\"\"\nTest per seismolab/data/gps_query.py\n\nCopertura richiesta dall'issue #23:\n- fetch_recent_measurements: caso principale, lista vuota, errore connessione\n- fetch_displacement_summary: caso principale, trend, nessuna misurazione\n- watch_anomalies: callback, nessuna anomalia, errore per singola stazione\n- GpsMeasurement: propriet\u00e0 calcolate, qualit\u00e0\n\"\"\"\n\nimport pytest\nfrom unittest.mock import MagicMock, call\nfrom datetime import datetime, timezone, timedelta\nimport psycopg2\n\nfrom seismolab.data.gps_query import (\n    fetch_recent_measurements, fetch_displacement_summary,\n    watch_anomalies, GpsMeasurement, DisplacementSummary,\n)\nfrom tests.conftest import BASE_TIME\n\n\n# Timestamp base per le misurazioni di test\nT0 = datetime(2023, 11, 14, 22, 0, 0, tzinfo=timezone.utc)\nT1 = T0 + timedelta(hours=1)\nT2 = T0 + timedelta(hours=2)\n\n\ndef _gps_row(station=\"ETNA01\", dt=T0,\n             lat=37.748, lon=14.994, elev=1500.0,\n             dn=1.2, de=0.8, du=-0.3, quality=2):\n    \"\"\"Costruisce una riga raw come restituita da psycopg2.\"\"\"\n    return (station, dt, lat, lon, elev, dn, de, du, quality)\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# fetch_recent_measurements\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestFetchRecentMeasurements:\n\n    def test_returns_measurements_for_station(self, mock_conn_factory):\n        rows = [_gps_row(\"ETNA01\", T0), _gps_row(\"ETNA01\", T1)]\n        conn, cursor = mock_conn_factory(rows)\n        result = fetch_recent_measurements(\"ETNA01\", hours=24, conn=conn)\n        assert len(result) == 2\n        assert all(m.station == \"ETNA01\" for m in result)\n\n    def test_returns_correct_fields(self, mock_conn_factory):\n        rows = [_gps_row(\"STRO02\", T0, dn=2.5, de=1.1, du=0.5)]\n        conn, cursor = mock_conn_factory(rows)\n        result = fetch_recent_measurements(\"STRO02\", hours=12, conn=conn)\n        m = result[0]\n        assert m.station == \"STRO02\"\n        assert m.recorded_at == T0\n        assert pytest.approx(m.delta_n) == 2.5\n        assert pytest.approx(m.delta_e) == 1.1\n\n    def test_empty_result_returns_empty_list(self, mock_conn_factory):\n        conn, cursor = mock_conn_factory([])\n        result = fetch_recent_measurements(\"ETNA01\", hours=1, conn=conn)\n        assert result == []\n\n    def test_uses_parametrized_query(self, mock_conn_factory):\n        \"\"\"Verifica che la query usi %s e non f-string.\"\"\"\n        conn, cursor = mock_conn_factory([])\n        fetch_recent_measurements(\"ETNA01\", hours=6, conn=conn)\n        cursor.execute.assert_called_once()\n        query, params = cursor.execute.call_args[0]\n        assert \"%s\" in query, \"La query deve usare placeholder %s\"\n        assert \"ETNA01\" not in query, \"Il valore non deve essere nella stringa SQL\"\n        assert \"ETNA01\" in str(params)\n\n    def test_raises_on_connection_error(self, mock_conn_factory):\n        conn, cursor = mock_conn_factory([])\n        cursor.execute.side_effect = psycopg2.OperationalError(\"connection refused\")\n        with pytest.raises(psycopg2.OperationalError):\n            fetch_recent_measurements(\"ETNA01\", conn=conn)\n\n    def test_raises_on_invalid_hours(self, mock_conn_factory):\n        conn, _ = mock_conn_factory([])\n        with pytest.raises(ValueError):\n            fetch_recent_measurements(\"ETNA01\", hours=0, conn=conn)\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# fetch_displacement_summary\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestFetchDisplacementSummary:\n\n    def test_returns_summary_with_correct_station(self, mock_conn_factory):\n        rows = [_gps_row(\"ETNA01\", T0, dn=1.0, de=0.5, du=0.2)]\n        conn, _ = mock_conn_factory(rows)\n        summary = fetch_displacement_summary(\"ETNA01\", days=7, conn=conn)\n        assert summary.station == \"ETNA01\"\n        assert summary.period_days == 7\n\n    def test_measurement_count_correct(self, mock_conn_factory):\n        rows = [_gps_row(dt=T0), _gps_row(dt=T1), _gps_row(dt=T2)]\n        conn, _ = mock_conn_factory(rows)\n        summary = fetch_displacement_summary(\"ETNA01\", conn=conn)\n        assert summary.measurement_count == 3\n\n    def test_empty_data_returns_zero_count(self, mock_conn_factory):\n        conn, _ = mock_conn_factory([])\n        summary = fetch_displacement_summary(\"ETNA01\", conn=conn)\n        assert summary.measurement_count == 0\n        assert summary.max_horizontal_mm is None\n\n    def test_increasing_trend_detected(self, mock_conn_factory):\n        \"\"\"Prima met\u00e0 con spostamenti bassi, seconda met\u00e0 con spostamenti alti.\"\"\"\n        rows = [\n            _gps_row(dt=T0, dn=0.5, de=0.3),          # prima met\u00e0\n            _gps_row(dt=T0 + timedelta(days=1), dn=0.5, de=0.3),\n            _gps_row(dt=T0 + timedelta(days=4), dn=2.0, de=1.5),  # seconda met\u00e0\n            _gps_row(dt=T0 + timedelta(days=5), dn=2.0, de=1.5),\n        ]\n        conn, _ = mock_conn_factory(rows)\n        summary = fetch_displacement_summary(\"ETNA01\", days=7, conn=conn)\n        assert summary.overall_trend == \"increasing\"\n\n    def test_raises_on_invalid_days(self, mock_conn_factory):\n        conn, _ = mock_conn_factory([])\n        with pytest.raises(ValueError):\n            fetch_displacement_summary(\"ETNA01\", days=-1, conn=conn)\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# watch_anomalies\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestWatchAnomalies:\n\n    def _make_conn_for_station(self, station, rows):\n        \"\"\"Mock connection che restituisce rows diverse per ogni stazione.\"\"\"\n        from unittest.mock import patch, MagicMock\n        # Usiamo side_effect su fetch_recent_measurements direttamente\n        return rows\n\n    def test_callback_called_for_anomaly(self, mock_conn_factory):\n        \"\"\"Un spostamento > soglia deve invocare il callback.\"\"\"\n        row = _gps_row(\"ETNA01\", T0, dn=5.0, de=5.0)  # magnitude ~7.07mm\n        conn, _ = mock_conn_factory([row])\n        callback = MagicMock()\n        count = watch_anomalies(\n            stations=[\"ETNA01\"],\n            threshold_mm=5.0,\n            callback=callback,\n            hours=1,\n            conn=conn,\n        )\n        assert count == 1\n        callback.assert_called_once()\n        args = callback.call_args[0]\n        assert args[0] == \"ETNA01\"\n\n    def test_no_callback_below_threshold(self, mock_conn_factory):\n        row = _gps_row(\"ETNA01\", T0, dn=1.0, de=0.5)  # magnitude ~1.12mm\n        conn, _ = mock_conn_factory([row])\n        callback = MagicMock()\n        count = watch_anomalies(\n            stations=[\"ETNA01\"],\n            threshold_mm=5.0,\n            callback=callback,\n            conn=conn,\n        )\n        assert count == 0\n        callback.assert_not_called()\n\n    def test_raises_on_invalid_threshold(self, mock_conn_factory):\n        conn, _ = mock_conn_factory([])\n        with pytest.raises(ValueError):\n            watch_anomalies([\"ETNA01\"], threshold_mm=0, callback=lambda s, m: None,\n                            conn=conn)\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# GpsMeasurement \u2014 propriet\u00e0 calcolate\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestGpsMeasurement:\n\n    def test_displacement_magnitude_correct(self):\n        m = GpsMeasurement(\n            station=\"TEST\", recorded_at=T0,\n            latitude=0, longitude=0, elevation=0,\n            delta_n=3.0, delta_e=4.0,\n        )\n        assert pytest.approx(m.displacement_magnitude) == 5.0  # 3-4-5\n\n    def test_displacement_magnitude_none_when_missing(self):\n        m = GpsMeasurement(\n            station=\"TEST\", recorded_at=T0,\n            latitude=0, longitude=0, elevation=0,\n        )\n        assert m.displacement_magnitude is None\n\n    def test_high_quality_flag(self):\n        m_high = GpsMeasurement(station=\"T\", recorded_at=T0,\n                                latitude=0, longitude=0, elevation=0, quality=2)\n        m_low = GpsMeasurement(station=\"T\", recorded_at=T0,\n                               latitude=0, longitude=0, elevation=0, quality=1)\n        assert m_high.is_high_quality is True\n        assert m_low.is_high_quality is False\n", label: "#23 \u2014 Query GPS", file: "seismolab/data/gps_query.py", testfile: "tests/test_gps.py" },
  "0":  { code: "\"\"\"\nRilevatore di eventi sismici tramite algoritmo STA/LTA.\n\nL'algoritmo Short-Term Average / Long-Term Average calcola in ogni istante\nil rapporto tra l'energia del segnale su una finestra breve (STA, sensibile\nagli onset) e una finestra lunga (LTA, rappresentativa del rumore di fondo).\nQuando il rapporto supera una soglia, viene dichiarato un evento.\n\nQuesto modulo \u00e8 usato per il monitoraggio in tempo reale:\ndetect_events viene chiamata su ogni nuova finestra di dati,\ne gli eventi rilevati vengono accumulati per il report giornaliero.\n\nIssue #0 \u2014 BUG SOTTILE:\nLa funzione detect_events ha un parametro con valore di default mutabile\n(events: list = []). In Python, i valori di default dei parametri sono\nvalutati UNA SOLA VOLTA alla definizione della funzione \u2014 non ad ogni\nchiamata. Questo significa che la stessa lista viene riutilizzata per\ntutte le chiamate che non passano esplicitamente il parametro events.\n\nSintomo osservabile: il conteggio degli eventi rilevati cresce\nmisteriosamente chiamata dopo chiamata, anche su segnale piatto.\nSu una singola chiamata il risultato \u00e8 corretto. Il bug emerge\nsolo quando la funzione viene chiamata pi\u00f9 volte in sequenza\n(es. nel loop di monitoring su pi\u00f9 stazioni).\n\nQuesto tipo di bug \u00e8 insidioso perch\u00e9:\n1. I test su singola chiamata passano\n2. Il problema \u00e8 riproducibile solo con pattern di chiamata specifici\n3. La causa non \u00e8 nella logica dell'algoritmo ma in Python stesso\n4. Il refactoring del parametro \u00e8 banale; trovare il problema non lo \u00e8\n\nIssue #0 (parte 2) \u2014 PROBLEMA DI PERFORMANCE:\ncompute_sta_lta ricalcola le somme STA e LTA da zero per ogni campione,\nscorrendo l'intera finestra ad ogni iterazione. La complessit\u00e0 \u00e8\nO(n * finestra): su una traccia di monitoraggio reale (una stazione\nregistra circa 8,6 milioni di campioni al giorno a 100 Hz) la funzione\ndiventa inutilizzabile, impiegando minuti per una singola traccia.\n\nSintomo osservabile: il tempo di esecuzione cresce in modo pi\u00f9 che\nlineare con la lunghezza della traccia. Su tracce brevi (test) \u00e8\nimpercettibile; su tracce reali blocca la pipeline di monitoraggio.\n\nLa correzione richiede di capire l'algoritmo: le somme STA e LTA possono\nessere mantenute in modo incrementale (sliding window), sottraendo il\ncampione che esce ed aggiungendo quello che entra, portando la\ncomplessit\u00e0 a O(n). Il risultato numerico deve restare identico.\n\"\"\"\n\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\n\n@dataclass\nclass SeismicEvent:\n    \"\"\"Evento sismico rilevato.\"\"\"\n    station: str\n    onset_time: float       # timestamp UNIX del P-onset\n    offset_time: float      # timestamp UNIX della coda\n    peak_ratio: float       # valore massimo STA/LTA durante l'evento\n    duration_s: float       # durata in secondi\n\n    @property\n    def is_significant(self) -> bool:\n        \"\"\"True se l'evento supera la soglia di significativit\u00e0.\"\"\"\n        return self.peak_ratio >= 3.0 and self.duration_s >= 1.0\n\n\n@dataclass\nclass DetectionResult:\n    \"\"\"Risultato della rilevazione su una traccia.\"\"\"\n    station: str\n    events: list[SeismicEvent]\n    sta_lta_ratios: list[float]    # serie temporale dei rapporti STA/LTA\n    threshold_used: float\n    samples_analyzed: int\n\n    @property\n    def event_count(self) -> int:\n        return len(self.events)\n\n    @property\n    def significant_events(self) -> list[SeismicEvent]:\n        return [e for e in self.events if e.is_significant]\n\n\ndef compute_sta_lta(\n    samples: list[float],\n    sample_rate: float,\n    sta_window_s: float = 1.0,\n    lta_window_s: float = 30.0,\n) -> list[float]:\n    \"\"\"\n    Calcola il rapporto STA/LTA per ogni campione della traccia.\n\n    Args:\n        samples:       lista di campioni di ampiezza\n        sample_rate:   campioni al secondo\n        sta_window_s:  finestra STA in secondi (default: 1s)\n        lta_window_s:  finestra LTA in secondi (default: 30s)\n\n    Returns:\n        Lista di rapporti STA/LTA, uno per campione.\n        I campioni nelle prime lta_window_s hanno rapporto 0.0.\n    \"\"\"\n    sta_n = max(1, int(sta_window_s * sample_rate))\n    lta_n = max(sta_n + 1, int(lta_window_s * sample_rate))\n    ratios = []\n\n    for i in range(len(samples)):\n        if i < lta_n:\n            ratios.append(0.0)\n            continue\n\n        # PERF (#0 parte 2): ricalcolo O(finestra) ad ogni campione.\n        # Su tracce lunghe questo rende la funzione inutilizzabile.\n        # Va sostituito con somme scorrevoli (sliding window) -> O(n).\n        sta_samples = [abs(s) for s in samples[i - sta_n:i]]\n        lta_samples = [abs(s) for s in samples[i - lta_n:i]]\n\n        sta = sum(sta_samples) / len(sta_samples)\n        lta = sum(lta_samples) / len(lta_samples)\n\n        ratios.append(sta / lta if lta > 1e-10 else 0.0)\n\n    return ratios\n\n\ndef detect_events(\n    station: str,\n    samples: list[float],\n    sample_rate: float,\n    threshold: float = 2.5,\n    sta_window_s: float = 1.0,\n    lta_window_s: float = 30.0,\n    events: list = [],          # BUG (#0): mutable default argument\n) -> DetectionResult:\n    \"\"\"\n    Rileva eventi sismici tramite STA/LTA su una traccia.\n\n    Args:\n        station:      codice stazione\n        samples:      campioni di ampiezza\n        sample_rate:  campioni al secondo\n        threshold:    soglia STA/LTA per dichiarare un evento (default: 2.5)\n        sta_window_s: finestra STA in secondi\n        lta_window_s: finestra LTA in secondi\n        events:       lista di eventi preesistenti da cui partire\n                      *** BUG: non usare [] come default \u2014 vedere issue #0 ***\n\n    Returns:\n        DetectionResult con gli eventi rilevati sulla traccia.\n\n    NOTA: il parametro `events=[]` \u00e8 un mutable default argument.\n    Ogni chiamata senza passare events esplicitamente condivide la stessa\n    lista. Gli eventi si accumulano tra chiamate successive.\n    \"\"\"\n    ratios = compute_sta_lta(samples, sample_rate, sta_window_s, lta_window_s)\n    threshold_n = threshold\n\n    in_event = False\n    event_start = 0\n    peak_ratio = 0.0\n\n    for i, ratio in enumerate(ratios):\n        t = i / sample_rate\n\n        if not in_event and ratio >= threshold_n:\n            in_event = True\n            event_start = t\n            peak_ratio = ratio\n\n        elif in_event:\n            if ratio > peak_ratio:\n                peak_ratio = ratio\n            if ratio < threshold_n * 0.7:   # isteresi al 70%\n                events.append(SeismicEvent(\n                    station=station,\n                    onset_time=event_start,\n                    offset_time=t,\n                    peak_ratio=peak_ratio,\n                    duration_s=t - event_start,\n                ))\n                in_event = False\n                peak_ratio = 0.0\n\n    # Chiude un evento ancora aperto a fine finestra\n    if in_event:\n        events.append(SeismicEvent(\n            station=station,\n            onset_time=event_start,\n            offset_time=len(samples) / sample_rate,\n            peak_ratio=peak_ratio,\n            duration_s=len(samples) / sample_rate - event_start,\n        ))\n\n    return DetectionResult(\n        station=station,\n        events=events,\n        sta_lta_ratios=ratios,\n        threshold_used=threshold,\n        samples_analyzed=len(samples),\n    )\n\n\ndef batch_detect(\n    station_data: dict[str, tuple[list[float], float]],\n    threshold: float = 2.5,\n    lta_window_s: float = 30.0,\n) -> dict[str, DetectionResult]:\n    \"\"\"\n    Esegue la rilevazione su pi\u00f9 stazioni.\n\n    Args:\n        station_data: {station: (samples, sample_rate)}\n        threshold:    soglia STA/LTA comune\n\n    Returns:\n        Dizionario {station: DetectionResult}\n\n    NOTA: questo wrapper chiama detect_events per ogni stazione.\n    Con il bug del mutable default, i risultati delle stazioni\n    successive includono gli eventi di tutte le precedenti.\n    \"\"\"\n    results = {}\n    for station, (samples, sample_rate) in station_data.items():\n        results[station] = detect_events(\n            station=station,\n            samples=samples,\n            sample_rate=sample_rate,\n            threshold=threshold,\n            lta_window_s=lta_window_s,\n            # BUG: events non viene passato esplicitamente\n        )\n    return results\n\n\ndef detect_events_continuous(\n    station: str,\n    chunks: list[list[float]],\n    sample_rate: float,\n    threshold: float = 2.5,\n    sta_window_s: float = 1.0,\n    lta_window_s: float = 30.0,\n) -> DetectionResult:\n    \"\"\"\n    Rilevazione su una traccia che arriva a blocchi consecutivi.\n\n    Le tracce di monitoraggio non arrivano tutte insieme: la pipeline riceve\n    record successivi della stessa stazione, uno dopo l'altro. Questa funzione\n    li analizza in sequenza e mantiene l'elenco degli eventi trovati\n    dall'inizio della traccia, restituendo un unico risultato cumulativo.\n\n    Usata da scripts/continuous_monitor.py sulla rete in esercizio.\n\n    Args:\n        station:     codice stazione\n        chunks:      blocchi consecutivi di campioni della stessa traccia\n        sample_rate: campioni al secondo\n\n    Returns:\n        DetectionResult con tutti gli eventi della traccia.\n    \"\"\"\n    accumulati: list = []\n    ultimo = None\n    campioni_totali = 0\n\n    for blocco in chunks:\n        ultimo = detect_events(\n            station=station, samples=blocco, sample_rate=sample_rate,\n            threshold=threshold, sta_window_s=sta_window_s,\n            lta_window_s=lta_window_s, events=accumulati,\n        )\n        accumulati = ultimo.events\n        campioni_totali += len(blocco)\n\n    if ultimo is None:\n        return DetectionResult(station=station, events=[], sta_lta_ratios=[],\n                               threshold_used=threshold, samples_analyzed=0)\n\n    return DetectionResult(\n        station=station, events=accumulati,\n        sta_lta_ratios=ultimo.sta_lta_ratios,\n        threshold_used=threshold, samples_analyzed=campioni_totali,\n    )\n", test: "\"\"\"\nTest per seismolab/processing/event_detector.py\n\nQuesti test dimostrano il bug del mutable default argument in detect_events.\nUsati dal docente durante la demo di triage in tempo reale.\n\nIl pattern: un test su singola chiamata passa; un test su chiamate multiple\nrivela il bug \u2014 il secondo test \u00e8 quello che il partecipante scrive\ndurante il triage mentre il docente guida la diagnosis.\n\"\"\"\n\nimport pytest\nimport math\nfrom seismolab.processing.event_detector import (\n    detect_events, batch_detect, compute_sta_lta,\n    SeismicEvent, DetectionResult,\n)\n\nSAMPLE_RATE = 100.0\n\n\nLTA_S = 5.0    # finestra LTA ridotta per i test (default 30s \u00e8 troppo lunga)\nLTA_N = int(LTA_S * SAMPLE_RATE)   # 500 campioni\n\n\ndef make_flat_signal(n: int = 3000, noise: float = 0.01) -> list[float]:\n    \"\"\"Segnale piatto con rumore minimo \u2014 nessun evento atteso.\"\"\"\n    import random\n    random.seed(42)\n    return [random.uniform(-noise, noise) for _ in range(n)]\n\n\ndef make_signal_with_event(n: int = 3000, event_start: int = 1500,\n                            event_duration: int = 200,\n                            amplitude: float = 5.0) -> list[float]:\n    \"\"\"Segnale con un singolo evento simulato (burst sinusoidale).\n    n deve essere > LTA_N + event_start per avere la finestra LTA riempita.\n    \"\"\"\n    samples = make_flat_signal(n)\n    for i in range(event_start, min(event_start + event_duration, n)):\n        t = (i - event_start) / event_duration\n        samples[i] += amplitude * math.sin(math.pi * t)\n    return samples\n\n\ndef _detect(station, samples, threshold=2.5):\n    \"\"\"Wrapper che passa esplicitamente events=[] per evitare il mutable default.\"\"\"\n    return detect_events(station, samples, SAMPLE_RATE,\n                         threshold=threshold,\n                         lta_window_s=LTA_S)\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# Test su singola chiamata \u2014 questi passano con il bug\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestSingleCall:\n\n    def test_no_events_on_flat_signal(self):\n        samples = make_flat_signal()\n        result = detect_events(\"ETNA01\", samples, SAMPLE_RATE,\n                               threshold=2.5, lta_window_s=LTA_S, events=[])\n        assert result.event_count == 0\n\n    def test_detects_event_in_signal(self):\n        samples = make_signal_with_event(amplitude=8.0)\n        result = detect_events(\"ETNA02\", samples, SAMPLE_RATE,\n                               threshold=2.5, lta_window_s=LTA_S, events=[])\n        assert result.event_count >= 1\n\n    def test_result_has_correct_station(self):\n        result = detect_events(\"STRO01\", make_flat_signal(), SAMPLE_RATE,\n                               lta_window_s=LTA_S, events=[])\n        assert result.station == \"STRO01\"\n\n    def test_threshold_affects_detection(self):\n        \"\"\"Soglia alta \u2192 meno eventi; soglia bassa \u2192 pi\u00f9 eventi.\"\"\"\n        samples = make_signal_with_event(amplitude=6.0)\n        high = detect_events(\"T\", samples, SAMPLE_RATE,\n                             threshold=5.0, lta_window_s=LTA_S, events=[])\n        low = detect_events(\"T\", samples, SAMPLE_RATE,\n                            threshold=1.5, lta_window_s=LTA_S, events=[])\n        assert low.event_count >= high.event_count\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# Test su chiamate multiple \u2014 questi RIVELANO il bug\n# Il docente guida il partecipante a scrivere questi test durante la demo\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestMultipleCalls:\n\n    def test_two_calls_independent_event_counts(self):\n        \"\"\"\n        QUESTO TEST FALLISCE con il bug del mutable default.\n\n        Con il fix (events=None e None \u2192 [] interno):\n          - result1: 1 evento\n          - result2: 0 eventi (segnale piatto)\n\n        Con il bug (events=[] shared):\n          - result1: 1 evento\n          - result2: 1 evento (eredita dall'accumulatore)\n        \"\"\"\n        signal_with_event = make_signal_with_event(amplitude=8.0)\n        flat_signal = make_flat_signal()\n\n        result1 = detect_events(\"ETNA01\", signal_with_event, SAMPLE_RATE,\n                                lta_window_s=LTA_S)\n        result2 = detect_events(\"ETNA02\", flat_signal, SAMPLE_RATE,\n                                lta_window_s=LTA_S)\n\n        assert result1.event_count >= 1, \"La prima chiamata deve rilevare l'evento\"\n        assert result2.event_count == 0, (\n            f\"La seconda chiamata su segnale piatto deve dare 0 eventi, \"\n            f\"trovato {result2.event_count}. \"\n            \"Questo \u00e8 il bug #0: mutable default argument.\"\n        )\n\n    def test_three_flat_calls_all_zero(self):\n        \"\"\"Tre chiamate su segnale piatto: ognuna deve dare 0 eventi.\"\"\"\n        for station in [\"ETNA01\", \"ETNA02\", \"STRO01\"]:\n            result = detect_events(station, make_flat_signal(), SAMPLE_RATE,\n                                   lta_window_s=LTA_S)\n            assert result.event_count == 0, (\n                f\"Stazione {station}: atteso 0, trovato {result.event_count}\"\n            )\n\n    def test_batch_detect_independent_per_station(self):\n        \"\"\"\n        batch_detect su stazioni con segnali diversi:\n        solo ETNA01 deve avere eventi.\n\n        Con il bug: l'evento di ETNA01 compare anche in ETNA02 e STRO01.\n        \"\"\"\n        station_data = {\n            \"ETNA01\": (make_signal_with_event(amplitude=8.0), SAMPLE_RATE),\n            \"ETNA02\": (make_flat_signal(), SAMPLE_RATE),\n            \"STRO01\": (make_flat_signal(), SAMPLE_RATE),\n        }\n        results = batch_detect(station_data, threshold=2.5, lta_window_s=LTA_S)\n        assert results[\"ETNA01\"].event_count >= 1\n        assert results[\"ETNA02\"].event_count == 0, (\n            f\"ETNA02: atteso 0, trovato {results['ETNA02'].event_count}\"\n        )\n        assert results[\"STRO01\"].event_count == 0, (\n            f\"STRO01: atteso 0, trovato {results['STRO01'].event_count}\"\n        )\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# compute_sta_lta \u2014 verifica dell'algoritmo\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nclass TestComputeStaLta:\n\n    def test_ratios_length_equals_samples(self):\n        samples = make_flat_signal(500)\n        ratios = compute_sta_lta(samples, SAMPLE_RATE)\n        assert len(ratios) == len(samples)\n\n    def test_initial_ratios_are_zero(self):\n        \"\"\"I primi lta_window_s secondi hanno ratio 0 (finestra LTA non riempita).\"\"\"\n        samples = make_flat_signal(1000)\n        ratios = compute_sta_lta(samples, SAMPLE_RATE, lta_window_s=10.0)\n        # I primi 1000 campioni (10s) devono avere ratio 0\n        first_n = int(10 * SAMPLE_RATE)\n        assert all(r == 0.0 for r in ratios[:first_n])\n\n    def test_ratio_increases_during_event(self):\n        \"\"\"Il ratio deve aumentare durante un evento.\"\"\"\n        samples = make_signal_with_event(n=3000, event_start=1500, amplitude=10.0)\n        ratios = compute_sta_lta(samples, SAMPLE_RATE, lta_window_s=LTA_S)\n        max_ratio = max(ratios)\n        assert max_ratio > 2.5\n\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# Issue #0 parte 2 \u2014 ottimizzazione a sliding window (performance)\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#\n# compute_sta_lta ricalcola le somme da zero ad ogni campione: O(n*finestra).\n# La correzione mantiene le somme in modo incrementale: O(n).\n# Questi test verificano che dopo l'ottimizzazione il RISULTATO NUMERICO\n# resti identico (correttezza) e che la funzione regga tracce lunghe.\n\nclass TestSlidingWindowOptimization:\n\n    def test_optimized_matches_reference_flat(self):\n        \"\"\"L'ottimizzazione deve dare gli stessi ratL su segnale piatto.\"\"\"\n        samples = make_flat_signal(2000)\n        ratios = compute_sta_lta(samples, SAMPLE_RATE, lta_window_s=LTA_S)\n        # Confronto con il calcolo di riferimento esplicito\n        expected = _reference_sta_lta(samples, SAMPLE_RATE, 1.0, LTA_S)\n        assert len(ratios) == len(expected)\n        for a, b in zip(ratios, expected):\n            assert abs(a - b) < 1e-9, \"Il risultato deve restare identico dopo l'ottimizzazione\"\n\n    def test_optimized_matches_reference_event(self):\n        \"\"\"L'ottimizzazione deve dare gli stessi ratio su segnale con evento.\"\"\"\n        samples = make_signal_with_event(n=3000, event_start=1500, amplitude=10.0)\n        ratios = compute_sta_lta(samples, SAMPLE_RATE, lta_window_s=LTA_S)\n        expected = _reference_sta_lta(samples, SAMPLE_RATE, 1.0, LTA_S)\n        for a, b in zip(ratios, expected):\n            assert abs(a - b) < 1e-9\n\n    def test_long_trace_completes_quickly(self):\n        \"\"\"Su una traccia lunga la funzione deve restare veloce (O(n)).\"\"\"\n        import time\n        samples = make_flat_signal(30000)   # 5 min @ 100Hz\n        t0 = time.time()\n        compute_sta_lta(samples, SAMPLE_RATE, lta_window_s=30.0)\n        elapsed = time.time() - t0\n        # Con O(n) deve stare ampiamente sotto il secondo.\n        # Con il bug O(n*finestra) impiega diversi secondi: il test fallisce.\n        assert elapsed < 0.5, (\n            f\"compute_sta_lta ha impiegato {elapsed:.2f}s su 30k campioni: \"\n            \"il ricalcolo O(n*finestra) va sostituito con somme scorrevoli.\"\n        )\n\n\ndef _reference_sta_lta(samples, sample_rate, sta_window_s, lta_window_s):\n    \"\"\"Calcolo STA/LTA di riferimento, esplicito e lento. Oracolo per i test.\"\"\"\n    sta_n = max(1, int(sta_window_s * sample_rate))\n    lta_n = max(sta_n + 1, int(lta_window_s * sample_rate))\n    out = []\n    for i in range(len(samples)):\n        if i < lta_n:\n            out.append(0.0)\n            continue\n        sta = sum(abs(s) for s in samples[i - sta_n:i]) / sta_n\n        lta = sum(abs(s) for s in samples[i - lta_n:i]) / lta_n\n        out.append(sta / lta if lta > 1e-10 else 0.0)\n    return out\n", label: "#0 \u2014 Conteggio eventi", file: "seismolab/processing/event_detector.py", testfile: "tests/test_event_detector.py" },
};

const EXTRA_HINT = {
  "17": "Nota per il valutatore, non menzionarla esplicitamente al partecipante: se il piano tecnico o il prompt riguarda l'override per stazione, controlla se il partecipante ha verificato ESATTAMENTE come il file di test esistente chiama la funzione (con quali argomenti, o senza) prima di assumere la forma dell'interfaccia. Se non l'ha fatto, la domanda guida dovrebbe spingerlo a rileggere quella chiamata specifica nel file di test, senza dirgli cosa trovera'.",
  "23": "",
  "0": "",
};

function buildSystemPrompt(issue, phase) {
  const src = SOURCES[issue];
  const base = "Sei un coach che aiuta un partecipante a un corso di sviluppo assistito da AI a scrivere " +
    (phase === "piano"
      ? "il piano tecnico (causa, fix, verifica) per un'issue di codice."
      : "un prompt efficace (contesto, comportamento attuale, comportamento corretto, vincolo) per chiedere a un modello AI di risolvere un'issue di codice.") +
    "\n\nNON scrivere mai tu la soluzione, non rivelare i valori esatti o gli schemi che il partecipante deve scoprire da solo leggendo il codice o i test. Il tuo lavoro e' indicare cosa e' generico, cosa manca, e fare UNA domanda guida che lo aiuti a trovare da solo il prossimo miglioramento.\n\n" +
    "CODICE SORGENTE (" + src.file + "):\n" + src.code + "\n\n" +
    "FILE DI TEST ESISTENTE, visibile e leggibile dal partecipante (" + src.testfile + "):\n" + src.test + "\n\n" +
    (EXTRA_HINT[issue] ? EXTRA_HINT[issue] + "\n\n" : "") +
    (phase === "piano"
      ? "Criteri di valutazione del piano tecnico:\n" +
        "- CAUSA: deve citare file e riga o funzione specifici, non parafrasare il docstring generico del modulo. Deve spiegare la conseguenza del problema, non solo il fatto. Se il testo sembra copiato o troppo simile al docstring in cima al file, segnalalo esplicitamente e chiedi di riformularlo come lo spiegherebbe a un collega senza il file aperto davanti.\n" +
        "- FIX: deve nominare il parametro esatto coinvolto (nome e tipo, es. 'un dizionario opzionale chiamato X'), non un termine generico come 'un parametro' o 'delle modifiche'. Deve descrivere il comportamento di default/retrocompatibilita' atteso quando il parametro non viene passato. Deve descrivere IL COMPORTAMENTO atteso, non implementarlo riga per riga.\n" +
        "- VERIFICA: deve contenere un comando pytest eseguibile e specifico (percorso del file), E almeno un caso di test concreto con valori numerici reali, non 'aggiungere un test'. Dai credito esplicito extra se il partecipante menziona di aver letto il file di test ESISTENTE per capire lo schema o il contratto atteso, non solo per evitare duplicati: e' la competenza chiave di questa fase.\n" +
        "- REGOLA CRITICA, applicala rigorosamente: dichiarare l'INTENZIONE di controllare qualcosa ('controllero' il test', 'verifichero' come viene chiamata la funzione') NON E' SUFFICIENTE e non conta come punto a favore da solo. Il piano deve riportare il RISULTATO CONCRETO di quel controllo: quale valore, quale livello, quale nome di chiave, quale comportamento ha trovato. Se il partecipante scrive che intende leggere un test ma non dice cosa ci ha trovato, questo va segnalato in 'generico_o_mancante' come intenzione dichiarata ma non completata, e 'pronto' deve essere false anche se il resto del piano e' forte. Una promessa di verifica futura non e' una verifica.\n\n"
      : "Criteri di valutazione del prompt (se mancano interi componenti, es. e' un prompt naive di una riga, elencali chiaramente come mancanti invece di valutarli):\n" +
        "- CONTESTO: deve puntare a file/riga/funzione specifici, non genericamente 'il codice'.\n" +
        "- COMPORTAMENTO ATTUALE: descrizione fattuale di cosa succede oggi, idealmente con un esempio concreto (valori reali), non un'impressione vaga.\n" +
        "- COMPORTAMENTO CORRETTO: deve specificare il comportamento atteso (input/output), NON la soluzione implementativa gia' scritta nel prompt stesso.\n" +
        "- VINCOLO: deve essere esplicito e verificabile (es. cosa non deve cambiare), non un generico 'non rompere niente'.\n" +
        "- REGOLA ANTI-RIPETIZIONE, importante: se il partecipante ha gia' citato un test specifico con la riga o la chiamata esatta (es. 'verificato in X, riga Y: la chiamata passa un solo argomento'), NON richiedere di riverificare la stessa citazione una seconda volta: a quel punto la domanda 'hai controllato il test?' e' gia' risposta. Se c'e' ancora un problema in quella frase, deve essere un problema DIVERSO — tipicamente che la frase descrive una scelta implementativa (struttura dati interna, dove vive una costante, nome di variabile privata) invece di un comportamento osservabile (input/output, valore di ritorno, side effect verificabile da un test). Distingui sempre questi due tipi di critica e non confonderli: 'non hai verificato' e 'questo e' implementazione non comportamento' sono errori diversi con correzioni diverse, e vanno segnalati con la domanda guida corrispondente, non con la stessa domanda riciclata.\n\n") +
    "Rispondi SOLO con un oggetto JSON valido, nessun testo prima o dopo, con esattamente questo schema:\n" +
    '{"buono": ["..."], "generico_o_mancante": ["..."], "domanda_guida": "...", "pronto": true}\n' +
    '"pronto" e\' true solo se ogni componente richiesto e\' specifico e concreto secondo i criteri sopra.';
  return base;
}

async function callClaude(systemPrompt, userText) {
  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 1000,
      messages: [
        { role: "user", content: systemPrompt + "\n\n---\n\nTesto del partecipante da valutare:\n\n" + userText }
      ],
    }),
  });
  const data = await response.json();
  const textBlock = (data.content || []).find((b) => b.type === "text");
  const raw = textBlock ? textBlock.text : "";
  const cleaned = raw.replace(/```json|```/g, "").trim();
  return JSON.parse(cleaned);
}

function Trace({ active }) {
  return (
    <svg viewBox="0 0 400 40" style={{ width: "100%", height: 40, display: "block" }} preserveAspectRatio="none">
      <line x1="0" y1="20" x2="400" y2="20" stroke="var(--line)" strokeWidth="1" />
      <path
        d="M0,20 L60,20 L72,4 L84,36 L96,10 L108,28 L120,20 L400,20"
        fill="none"
        stroke="var(--accent)"
        strokeWidth="2"
        strokeLinejoin="round"
        strokeLinecap="round"
        style={{
          strokeDasharray: 460,
          strokeDashoffset: active ? 0 : 460,
          transition: active ? "stroke-dashoffset 1.1s linear" : "none",
          animation: active ? "trace-loop 1.1s linear infinite" : "none",
        }}
      />
    </svg>
  );
}

export default function Coach() {
  const [issue, setIssue] = useState("17");
  const [phase, setPhase] = useState("piano");
  const [text, setText] = useState("");
  const [loading, setLoading] = useState(false);
  const [feedback, setFeedback] = useState(null);
  const [error, setError] = useState(null);
  const [history, setHistory] = useState([]);
  const loadedRef = useRef(false);

  useEffect(() => {
    (async () => {
      try {
        const r = await window.storage.get("coach-history");
        if (r && r.value) setHistory(JSON.parse(r.value));
      } catch (e) { /* nessuna storia precedente */ }
      loadedRef.current = true;
    })();
  }, []);

  useEffect(() => {
    if (!loadedRef.current) return;
    window.storage.set("coach-history", JSON.stringify(history)).catch(() => {});
  }, [history]);

  async function handleEvaluate() {
    if (!text.trim() || loading) return;
    setLoading(true);
    setError(null);
    setFeedback(null);
    try {
      const sys = buildSystemPrompt(issue, phase);
      const result = await callClaude(sys, text);
      setFeedback(result);
      setHistory((h) => [
        { issue, phase, text, result, ts: new Date().toLocaleTimeString("it-IT") },
        ...h,
      ].slice(0, 20));
    } catch (e) {
      setError("Non sono riuscito a leggere la risposta. Riprova.");
    } finally {
      setLoading(false);
    }
  }

  const placeholder = phase === "piano"
    ? "Scrivi qui il tuo piano tecnico: causa, fix, verifica..."
    : "Scrivi qui il tuo prompt: contesto, comportamento attuale, comportamento corretto, vincolo...";

  return (
    <div style={{
      "--bg": "#12161C", "--panel": "#1B222C", "--panel2": "#222B37",
      "--accent": "#D98E3B", "--teal": "#5FA8A0", "--text": "#EDE6D6",
      "--muted": "#8B93A1", "--line": "#2C3543", "--red": "#C4634A",
      background: "var(--bg)", color: "var(--text)", minHeight: "100vh", width: "100%",
      fontFamily: "-apple-system, 'Segoe UI', system-ui, sans-serif",
      padding: "40px 20px 60px", boxSizing: "border-box",
      display: "flex", justifyContent: "center",
    }}>
      <style>{`
        @keyframes trace-loop {
          0% { stroke-dashoffset: 460; }
          100% { stroke-dashoffset: 0; }
        }
        .st-btn { transition: border-color .15s, background .15s, color .15s; }
        .st-btn:hover { border-color: var(--accent) !important; }
        textarea:focus, .st-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
        ::selection { background: var(--accent); color: #12161C; }
      `}</style>

      <div style={{ maxWidth: 720, width: "100%" }}>
        <div style={{ fontFamily: "ui-monospace, 'SF Mono', 'Cascadia Code', monospace",
                       fontSize: 11.5, letterSpacing: "0.12em", color: "var(--teal)",
                       textTransform: "uppercase" }}>
          SeismoLab Core &middot; Modulo 4
        </div>
        <h1 style={{ fontSize: 26, margin: "6px 0 2px", fontWeight: 700, letterSpacing: "-0.01em" }}>
          Coach &mdash; piano tecnico &amp; prompt
        </h1>
        <p style={{ color: "var(--muted)", fontSize: 14.5, margin: "0 0 20px", lineHeight: 1.5 }}>
          Incolla quello che hai scritto. Non ti do la risposta: ti dico cosa &egrave; specifico,
          cosa &egrave; ancora generico, e ti faccio una domanda per il prossimo giro.
        </p>

        <Trace active={loading} />

        <div style={{ display: "flex", gap: 8, margin: "18px 0 10px", flexWrap: "wrap" }}>
          {Object.entries(SOURCES).map(([key, s]) => (
            <button key={key} className="st-btn" onClick={() => { setIssue(key); setFeedback(null); }}
              style={{
                flex: "1 1 150px", padding: "10px 12px", borderRadius: 8,
                border: `1px solid ${issue === key ? "var(--accent)" : "var(--line)"}`,
                background: issue === key ? "var(--panel2)" : "var(--panel)",
                color: issue === key ? "var(--text)" : "var(--muted)",
                fontSize: 13, fontWeight: 600, cursor: "pointer", textAlign: "left",
              }}>
              {s.label}
            </button>
          ))}
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
          {[["piano", "Piano tecnico"], ["prompt", "Prompt"]].map(([key, label]) => (
            <button key={key} className="st-btn" onClick={() => { setPhase(key); setFeedback(null); }}
              style={{
                padding: "8px 16px", borderRadius: 999,
                border: `1px solid ${phase === key ? "var(--accent)" : "var(--line)"}`,
                background: phase === key ? "var(--accent)" : "transparent",
                color: phase === key ? "#1A130A" : "var(--muted)",
                fontSize: 13, fontWeight: 700, cursor: "pointer",
              }}>
              {label}
            </button>
          ))}
        </div>

        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder={placeholder}
          rows={7}
          style={{
            width: "100%", boxSizing: "border-box", background: "var(--panel)",
            border: "1px solid var(--line)", borderRadius: 10, color: "var(--text)",
            padding: "14px 16px", fontSize: 14.5, lineHeight: 1.6,
            fontFamily: "ui-monospace, 'SF Mono', 'Cascadia Code', monospace",
            resize: "vertical",
          }}
        />

        <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 10 }}>
          <button onClick={handleEvaluate} disabled={loading || !text.trim()}
            style={{
              padding: "10px 22px", borderRadius: 8, border: "none",
              background: loading || !text.trim() ? "var(--line)" : "var(--accent)",
              color: loading || !text.trim() ? "var(--muted)" : "#1A130A",
              fontSize: 14, fontWeight: 700,
              cursor: loading || !text.trim() ? "default" : "pointer",
            }}>
            {loading ? "Valutazione in corso\u2026" : "Valuta"}
          </button>
        </div>

        {error && (
          <div style={{ marginTop: 16, color: "var(--red)", fontSize: 13.5 }}>{error}</div>
        )}

        {feedback && (
          <div style={{
            marginTop: 22, background: "var(--panel)", border: "1px solid var(--line)",
            borderRadius: 12, padding: "18px 20px",
          }}>
            <div style={{
              display: "inline-block", padding: "4px 12px", borderRadius: 999,
              fontSize: 12, fontWeight: 700, marginBottom: 14,
              background: feedback.pronto ? "rgba(95,168,160,0.18)" : "rgba(217,142,61,0.18)",
              color: feedback.pronto ? "var(--teal)" : "var(--accent)",
            }}>
              {feedback.pronto ? "Pronto per procedere" : "Da rivedere"}
            </div>

            {feedback.buono && feedback.buono.length > 0 && (
              <div style={{ marginBottom: 14 }}>
                <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase",
                              letterSpacing: "0.08em", marginBottom: 6 }}>Cosa funziona</div>
                {feedback.buono.map((b, i) => (
                  <div key={i} style={{ fontSize: 14, lineHeight: 1.5, marginBottom: 4 }}>
                    <span style={{ color: "var(--teal)" }}>&#10003;&nbsp;</span>{b}
                  </div>
                ))}
              </div>
            )}

            {feedback.generico_o_mancante && feedback.generico_o_mancante.length > 0 && (
              <div style={{ marginBottom: 14 }}>
                <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase",
                              letterSpacing: "0.08em", marginBottom: 6 }}>Generico o mancante</div>
                {feedback.generico_o_mancante.map((b, i) => (
                  <div key={i} style={{ fontSize: 14, lineHeight: 1.5, marginBottom: 4 }}>
                    <span style={{ color: "var(--accent)" }}>&#9651;&nbsp;</span>{b}
                  </div>
                ))}
              </div>
            )}

            {feedback.domanda_guida && (
              <div style={{
                marginTop: 12, paddingTop: 14, borderTop: "1px solid var(--line)",
                fontSize: 14.5, fontStyle: "italic", color: "var(--text)",
              }}>
                {feedback.domanda_guida}
              </div>
            )}
          </div>
        )}

        {history.length > 0 && (
          <div style={{ marginTop: 30 }}>
            <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase",
                          letterSpacing: "0.08em", marginBottom: 8 }}>
              Tentativi precedenti ({history.length})
            </div>
            {history.slice(0, 6).map((h, i) => (
              <div key={i} style={{
                display: "flex", justifyContent: "space-between", alignItems: "center",
                padding: "8px 0", borderBottom: "1px solid var(--line)", fontSize: 13,
              }}>
                <span style={{ color: "var(--muted)" }}>
                  {h.ts} &middot; {SOURCES[h.issue].label} &middot; {h.phase === "piano" ? "Piano tecnico" : "Prompt"}
                </span>
                <span style={{
                  color: h.result && h.result.pronto ? "var(--teal)" : "var(--accent)",
                  fontWeight: 700, fontSize: 12,
                }}>
                  {h.result && h.result.pronto ? "Pronto" : "Da rivedere"}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
